最终只返回JSON对象 {"files":[{"path":"windows.mjs","content":"完整文件内容"}]}，只允许交付 windows.mjs 一个业务文件；不新增测试文件，不附说明或Markdown代码围栏。","context":{"customDescription":"以下是合成演示文件，所有臂可见材料相同。时间窗口单位不影响本次区间逻辑。","technologyStack":[],"dependencies":[],"directoryTree":["windows.mjs"],"fileSnippets":[{"path":"windows.mjs","language":"javascript","content":"export function combineWindows(windows) {
  const ordered = windows.map(window => ({ ...window }))
    .sort((a, b) => a.start - b.start || a.end - b.end);
  const result = [];
  for (const window of ordered) {
    const last = result.at(-1);
    if (!last || window.start > last.end) {
      result.push(window);
    } else {
      last.end = Math.max(last.end, window.end);
    }
  }
  return result;
}
